[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$Path)
$ErrorActionPreference='Stop';$d=[IO.Path]::GetFullPath($Path);$m=Get-Content (Join-Path $d 'fixture.json') -Raw|ConvertFrom-Json;if($m.product_id -ne 'spectra' -or $m.synthetic -ne $true -or $m.installable -ne $false){throw 'CONTROL_IDENTITY_INVALID'};foreach($p in @('implementation','support-only')){$records=Get-Content (Join-Path $d "$p\records.json") -Raw|ConvertFrom-Json;if(@($records).Count -ne 4){throw "CONTROL_RECORD_COUNT_INVALID:$p"};foreach($r in @($records)){if([string]$r.profile -ne $p -or [string]$r.id -notmatch '^(PRJ|TKT|RISK|DEC)-SYNTHETIC-CONTROL$'){throw "CONTROL_RECORD_INVALID:$p"}}};$c=Get-Content (Join-Path $d 'control-records.json') -Raw|ConvertFrom-Json;if(@($c.phases).Count -ne 7 -or @($c.work_packages).Count -ne 1 -or @($c.roles).Count -ne 1 -or @($c.risks).Count -ne 1 -or @($c.decisions).Count -ne 1){throw 'CONTROL_OPERATIONAL_RECORDS_INCOMPLETE'};if([string]$c.work_packages[0].due_date -notmatch '^\d{4}-\d{2}-\d{2}$'){throw 'CONTROL_DATE_INVALID'};Write-Host 'PASS: Synthetic implementation/support-only control fixture validates read-only.'
